-- calc_project_metadata_domain_count
-- Field: ProjectMetadata.DomainCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_project_metadata_domain_count(p_project_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM rulebook_domains WHERE project = (SELECT NULLIF(project_id, '') FROM project_metadata WHERE project_id = p_project_id)))::numeric;
$$ LANGUAGE sql STABLE;

