CREATE OR REPLACE FUNCTION calc_acceptance_criteria_name(p_acceptance_criterion_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(acceptance_criterion_id, '') FROM acceptance_criteria WHERE acceptance_criterion_id = p_acceptance_criterion_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_met_flag
-- Field: AcceptanceCriteria.MetFlag
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_met_flag(p_acceptance_criterion_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN COALESCE((SELECT is_met FROM acceptance_criteria WHERE acceptance_criterion_id = p_acceptance_criterion_id), FALSE) THEN (1)::text ELSE (0)::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_is_inconsistent_with_story
-- Field: AcceptanceCriteria.IsInconsistentWithStory
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_is_inconsistent_with_story(p_acceptance_criterion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (((COALESCE(calc_acceptance_criteria_story_is_done(p_acceptance_criterion_id), FALSE) = 'true') AND NOT (COALESCE((SELECT is_met FROM acceptance_criteria WHERE acceptance_criterion_id = p_acceptance_criterion_id), FALSE))))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_share_of_story
-- Field: AcceptanceCriteria.ShareOfStory
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_share_of_story(p_acceptance_criterion_id TEXT)
RETURNS NUMERIC AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_acceptance_criteria_story_criterion_count(p_acceptance_criterion_id) AS val) SELECT (CASE WHEN (COALESCE((SELECT val FROM __erb_dedup_v1), 0))::NUMERIC = 0 THEN (0)::text ELSE (ROUND(((COALESCE(100, 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0), 0)))::NUMERIC, (0)::INTEGER))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_criterion_state
-- Field: AcceptanceCriteria.CriterionState
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_criterion_state(p_acceptance_criterion_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_acceptance_criteria_is_inconsistent_with_story(p_acceptance_criterion_id) THEN ('contradicts-story')::text ELSE (CASE WHEN COALESCE((SELECT is_met FROM acceptance_criteria WHERE acceptance_criterion_id = p_acceptance_criterion_id), FALSE) THEN ('met')::text ELSE ('pending')::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_needs_review
-- Field: AcceptanceCriteria.NeedsReview
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_needs_review(p_acceptance_criterion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (calc_acceptance_criteria_criterion_state(p_acceptance_criterion_id) = 'contradicts-story')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_story_is_ahead_of_criterion
-- Field: AcceptanceCriteria.StoryIsAheadOfCriterion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_story_is_ahead_of_criterion(p_acceptance_criterion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((NOT (COALESCE((SELECT is_met FROM acceptance_criteria WHERE acceptance_criterion_id = p_acceptance_criterion_id), FALSE)) AND (COALESCE(calc_acceptance_criteria_story_derived_progress(p_acceptance_criterion_id), 0))::NUMERIC >= 50));
$$ LANGUAGE sql STABLE;

-- calc_consistency_rules_name
-- Field: ConsistencyRules.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_consistency_rules_name(p_consistency_rule_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(rule_code, '') FROM consistency_rules WHERE consistency_rule_id = p_consistency_rule_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_consistency_rules_finding_count
-- Field: ConsistencyRules.FindingCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_consistency_rules_finding_count(p_consistency_rule_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM consistency_findings WHERE rule = (SELECT NULLIF(consistency_rule_id, '') FROM consistency_rules WHERE consistency_rule_id = p_consistency_rule_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_consistency_rules_is_critical
-- Field: ConsistencyRules.IsCritical
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_consistency_rules_is_critical(p_consistency_rule_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(severity, '') FROM consistency_rules WHERE consistency_rule_id = p_consistency_rule_id) = 'critical')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_consistency_rules_is_repo_scope
-- Field: ConsistencyRules.IsRepoScope
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_consistency_rules_is_repo_scope(p_consistency_rule_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(scope, '') FROM consistency_rules WHERE consistency_rule_id = p_consistency_rule_id) <> 'demo')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_consistency_rules_open_finding_count
-- Field: ConsistencyRules.OpenFindingCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_consistency_rules_open_finding_count(p_consistency_rule_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(SUM((calc_consistency_findings_open_flag(consistency_finding_id))::numeric), 0) FROM consistency_findings WHERE rule = p_consistency_rule_id))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_consistency_rules_has_findings
-- Field: ConsistencyRules.HasFindings
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_consistency_rules_has_findings(p_consistency_rule_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_consistency_rules_finding_count(p_consistency_rule_id))::NUMERIC > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_consistency_rules_is_satisfied
-- Field: ConsistencyRules.IsSatisfied
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_consistency_rules_is_satisfied(p_consistency_rule_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_consistency_rules_open_finding_count(p_consistency_rule_id))::NUMERIC = 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_consistency_rules_satisfied_flag
-- Field: ConsistencyRules.SatisfiedFlag
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_consistency_rules_satisfied_flag(p_consistency_rule_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN (calc_consistency_rules_open_finding_count(p_consistency_rule_id))::NUMERIC = 0 THEN (1)::text ELSE (0)::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_consistency_rules_accepted_or_fixed_count
-- Field: ConsistencyRules.AcceptedOrFixedCount
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_consistency_rules_accepted_or_fixed_count(p_consistency_rule_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_consistency_rules_finding_count(p_consistency_rule_id)) AS v) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_consistency_rules_open_finding_count(p_consistency_rule_id)) AS v) __safe_numeric), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_consistency_rules_open_critical_flag
-- Field: ConsistencyRules.OpenCriticalFlag
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_consistency_rules_open_critical_flag(p_consistency_rule_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN (calc_consistency_rules_is_critical(p_consistency_rule_id) AND (calc_consistency_rules_open_finding_count(p_consistency_rule_id))::NUMERIC > 0) THEN (1)::text ELSE (0)::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_consistency_rules_rule_state
-- Field: ConsistencyRules.RuleState
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_consistency_rules_rule_state(p_consistency_rule_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_consistency_rules_is_satisfied(p_consistency_rule_id) THEN ('satisfied')::text ELSE (CASE WHEN (calc_consistency_rules_open_critical_flag(p_consistency_rule_id))::NUMERIC = 1 THEN ('critical-open')::text ELSE ('open')::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_consistency_rules_resolution_percent
-- Field: ConsistencyRules.ResolutionPercent
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_consistency_rules_resolution_percent(p_consistency_rule_id TEXT)
RETURNS NUMERIC AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_consistency_rules_finding_count(p_consistency_rule_id) AS val) SELECT (CASE WHEN ((SELECT val FROM __erb_dedup_v1))::NUMERIC = 0 THEN (100)::text ELSE (ROUND(((COALESCE(100, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_consistency_rules_accepted_or_fixed_count(p_consistency_rule_id)) AS v) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0), 0))) AS v) __safe_numeric), 0)))::NUMERIC, (0)::INTEGER))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_consistency_rules_rule_label
-- Field: ConsistencyRules.RuleLabel
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_consistency_rules_rule_label(p_consistency_rule_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(rule_code, '') FROM consistency_rules WHERE consistency_rule_id = p_consistency_rule_id), ' [', calc_consistency_rules_rule_state(p_consistency_rule_id), ']'))::text;
$$ LANGUAGE sql STABLE;

-- calc_consistency_rules_is_sweep_priority
-- Field: ConsistencyRules.IsSweepPriority
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_consistency_rules_is_sweep_priority(p_consistency_rule_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_consistency_rules_rule_state(p_consistency_rule_id) <> 'satisfied' AND (calc_consistency_rules_resolution_percent(p_consistency_rule_id))::NUMERIC < 50));
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_rule_severity
-- Field: ConsistencyFindings.RuleSeverity
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: Severity from related ConsistencyRules


CREATE OR REPLACE FUNCTION calc_consistency_findings_rule_severity(p_consistency_finding_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT severity::text FROM consistency_rules WHERE consistency_rule_id = (SELECT rule FROM consistency_findings WHERE consistency_finding_id = p_consistency_finding_id));
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_rule_is_scanner_derived
-- Field: ConsistencyFindings.RuleIsScannerDerived
-- Type: lookup | DataType: boolean | Returns: BOOLEAN
-- Lookup: IsScannerDerived from related ConsistencyRules


CREATE OR REPLACE FUNCTION calc_consistency_findings_rule_is_scanner_derived(p_consistency_finding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (SELECT is_scanner_derived::boolean FROM consistency_rules WHERE consistency_rule_id = (SELECT rule FROM consistency_findings WHERE consistency_finding_id = p_consistency_finding_id));
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_rule_code
-- Field: ConsistencyFindings.RuleCode
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: RuleCode from related ConsistencyRules


CREATE OR REPLACE FUNCTION calc_consistency_findings_rule_code(p_consistency_finding_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT rule_code::text FROM consistency_rules WHERE consistency_rule_id = (SELECT rule FROM consistency_findings WHERE consistency_finding_id = p_consistency_finding_id));
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_domain_name
-- Field: ConsistencyFindings.DomainName
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: DomainName from related RulebookDomains


CREATE OR REPLACE FUNCTION calc_consistency_findings_domain_name(p_consistency_finding_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT domain_name::text FROM rulebook_domains WHERE domain_id = (SELECT domain FROM consistency_findings WHERE consistency_finding_id = p_consistency_finding_id));
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_domain_finding_count
-- Field: ConsistencyFindings.DomainFindingCount
-- Type: lookup | DataType: number | Returns: NUMERIC
-- Lookup: FindingCount from related RulebookDomains


CREATE OR REPLACE FUNCTION calc_consistency_findings_domain_finding_count(p_consistency_finding_id TEXT)
RETURNS NUMERIC AS $$
  SELECT calc_rulebook_domains_finding_count((SELECT domain FROM consistency_findings WHERE consistency_finding_id = p_consistency_finding_id));
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_rule_finding_count
-- Field: ConsistencyFindings.RuleFindingCount
-- Type: lookup | DataType: number | Returns: NUMERIC
-- Lookup: FindingCount from related ConsistencyRules


CREATE OR REPLACE FUNCTION calc_consistency_findings_rule_finding_count(p_consistency_finding_id TEXT)
RETURNS NUMERIC AS $$
  SELECT calc_consistency_rules_finding_count((SELECT rule FROM consistency_findings WHERE consistency_finding_id = p_consistency_finding_id));
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_domain_open_finding_count
-- Field: ConsistencyFindings.DomainOpenFindingCount
-- Type: lookup | DataType: number | Returns: NUMERIC
-- Lookup: OpenFindingCount from related RulebookDomains


CREATE OR REPLACE FUNCTION calc_consistency_findings_domain_open_finding_count(p_consistency_finding_id TEXT)
RETURNS NUMERIC AS $$
  SELECT calc_rulebook_domains_open_finding_count((SELECT domain FROM consistency_findings WHERE consistency_finding_id = p_consistency_finding_id));
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_rule_open_finding_count
-- Field: ConsistencyFindings.RuleOpenFindingCount
-- Type: lookup | DataType: number | Returns: NUMERIC
-- Lookup: OpenFindingCount from related ConsistencyRules


CREATE OR REPLACE FUNCTION calc_consistency_findings_rule_open_finding_count(p_consistency_finding_id TEXT)
RETURNS NUMERIC AS $$
  SELECT calc_consistency_rules_open_finding_count((SELECT rule FROM consistency_findings WHERE consistency_finding_id = p_consistency_finding_id));
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_rule_is_satisfied
-- Field: ConsistencyFindings.RuleIsSatisfied
-- Type: lookup | DataType: boolean | Returns: BOOLEAN
-- Lookup: IsSatisfied from related ConsistencyRules


CREATE OR REPLACE FUNCTION calc_consistency_findings_rule_is_satisfied(p_consistency_finding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT calc_consistency_rules_is_satisfied((SELECT rule FROM consistency_findings WHERE consistency_finding_id = p_consistency_finding_id));
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_domain_grade
-- Field: ConsistencyFindings.DomainGrade
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: ConsistencyGrade from related RulebookDomains


CREATE OR REPLACE FUNCTION calc_consistency_findings_domain_grade(p_consistency_finding_id TEXT)
RETURNS TEXT AS $$
  SELECT calc_rulebook_domains_consistency_grade((SELECT domain FROM consistency_findings WHERE consistency_finding_id = p_consistency_finding_id));
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_name
-- Field: ConsistencyFindings.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_consistency_findings_name(p_consistency_finding_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT(COALESCE((SELECT NULLIF(domain, '') FROM consistency_findings WHERE consistency_finding_id = p_consistency_finding_id), 'repo'), ' x ', (SELECT NULLIF(rule, '') FROM consistency_findings WHERE consistency_finding_id = p_consistency_finding_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_is_open
-- Field: ConsistencyFindings.IsOpen
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_consistency_findings_is_open(p_consistency_finding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(status, '') FROM consistency_findings WHERE consistency_finding_id = p_consistency_finding_id) = 'open')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_open_flag
-- Field: ConsistencyFindings.OpenFlag
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_consistency_findings_open_flag(p_consistency_finding_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN (SELECT NULLIF(status, '') FROM consistency_findings WHERE consistency_finding_id = p_consistency_finding_id) = 'open' THEN (1)::text ELSE (0)::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_is_repo_scope
-- Field: ConsistencyFindings.IsRepoScope
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_consistency_findings_is_repo_scope(p_consistency_finding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(domain, '') FROM consistency_findings WHERE consistency_finding_id = p_consistency_finding_id) IS NULL)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_is_open_critical
-- Field: ConsistencyFindings.IsOpenCritical
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_consistency_findings_is_open_critical(p_consistency_finding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_consistency_findings_is_open(p_consistency_finding_id) AND calc_consistency_findings_rule_severity(p_consistency_finding_id) = 'critical'))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_is_hand_closable
-- Field: ConsistencyFindings.IsHandClosable
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_consistency_findings_is_hand_closable(p_consistency_finding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_consistency_findings_is_open(p_consistency_finding_id) AND NOT (calc_consistency_findings_rule_is_scanner_derived(p_consistency_finding_id))))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_is_sole_finding_on_domain
-- Field: ConsistencyFindings.IsSoleFindingOnDomain
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_consistency_findings_is_sole_finding_on_domain(p_consistency_finding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_consistency_findings_domain_finding_count(p_consistency_finding_id), 0))::NUMERIC = 1)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_is_sole_blocker
-- Field: ConsistencyFindings.IsSoleBlocker
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_consistency_findings_is_sole_blocker(p_consistency_finding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_consistency_findings_is_open(p_consistency_finding_id) AND (COALESCE(calc_consistency_findings_domain_open_finding_count(p_consistency_finding_id), 0))::NUMERIC = 1));
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_priority
-- Field: ConsistencyFindings.Priority
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_consistency_findings_priority(p_consistency_finding_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_consistency_findings_is_open_critical(p_consistency_finding_id) THEN ('P1')::text ELSE (CASE WHEN calc_consistency_findings_is_sole_blocker(p_consistency_finding_id) THEN ('P2')::text ELSE (CASE WHEN calc_consistency_findings_is_open(p_consistency_finding_id) THEN ('P3')::text ELSE ('closed')::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_is_last_mile
-- Field: ConsistencyFindings.IsLastMile
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_consistency_findings_is_last_mile(p_consistency_finding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_consistency_findings_is_sole_blocker(p_consistency_finding_id) AND COALESCE(calc_consistency_findings_domain_grade(p_consistency_finding_id), '') = 'minor'))::boolean;
$$ LANGUAGE sql STABLE;

