  SELECT (CONCAT((SELECT NULLIF(from_skill, '') FROM skill_routes WHERE skill_route_id = p_skill_route_id), ' -> ', (SELECT NULLIF(to_skill, '') FROM skill_routes WHERE skill_route_id = p_skill_route_id), ' [', calc_skill_routes_edge_class(p_skill_route_id), ']'))::text;
