$$ LANGUAGE sql STABLE;

-- calc_project_slot_witnesses_required_here_flag
-- Field: ProjectSlotWitnesses.RequiredHereFlag
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_project_slot_witnesses_required_here_flag(p_project_slot_witness_id TEXT)
