-- Field: AddToolCatalog.IsLocalProxy
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_add_tool_catalog_is_local_proxy(p_tool_id TEXT)
